diff --git a/CHANGELOG.md b/CHANGELOG.md
index 62520fd2c..5be46549d 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -21,6 +21,9 @@ All notable changes to `entire-brain` are recorded here. The format follows
   files the session's checkpoint touched) so it links to the file's symbols.
   The indexer version moves, so the next refresh re-indexes existing
   sessions (#600).
+- The pattern corpus works out a Codex session's repository root from the
+  same edit records it stores file refs from, so the two can no longer
+  disagree about which records are edits.
 - `recall --evidence` no longer returns harness-injected `<system-reminder>`
   text as `role: "user"` evidence. User-role strings and text blocks now go
   through the same wrapper filter as the conversation reader, so reminders,
diff --git a/docs/pattern_v2.md b/docs/pattern_v2.md
index 073ed078c..da00dbefb 100644
--- a/docs/pattern_v2.md
+++ b/docs/pattern_v2.md
@@ -1063,7 +1063,7 @@ Validation:
 **Phase 2 landed: episodes as brain events.** Corpus episodes now carry the
 operational evidence Phase 3 corroboration needs (`pattern_corpus_enrich.go`):
 - `episode_commands` get exit codes + `failed` (correlated to outputs by call id) and `episodes.exit_fails`. A current Codex command (the cli's item path: a compact `Bash` block) carries no exit code, so its `result.status:"error"` is stored as `failed` with `exit_code` NULL.
-- `episode_files` (apply_patch `*** Update/Add/Delete File`, Claude `edit/write/read` tools, compact codex `FileChange` changes by `kind`, with a `move_path` as delete + add) with actions; `episodes.files` JSON. A `FileChange` path is absolute. The session's root is the prefix its paths share with the repo-relative `files_touched` its checkpoint records: each root its paths give scores one per distinct path that is a touched file under it, and the highest score wins. Paths under it are stored relative to it, so they link like a patch path whichever checkout the session ran in or the corpus is built from. With no match or a tied score, paths are stored as written. So is any path with a `..` segment, since the OS resolves `..` after symlinks, and a session with one gets no root at all, since leaving that path out could hand the root to the rest. Because the root comes from the checkpoint, a session whose exported checkpoint changes is re-indexed even if its transcript did not.
+- `episode_files` (apply_patch `*** Update/Add/Delete File`, Claude `edit/write/read` tools, compact codex `FileChange` changes by `kind`, with a `move_path` as delete + add) with actions; `episodes.files` JSON. A `FileChange` path is absolute. The session's root is the prefix its paths share with the repo-relative `files_touched` its checkpoint records: each root its paths give scores one per distinct path that is a touched file under it, and the highest score wins. Paths under it are stored relative to it, so they link like a patch path whichever checkout the session ran in or the corpus is built from. With no match or a tied score, paths are stored as written. So is any path with a `..` segment, since the OS resolves `..` after symlinks, and a session with one gets no root at all, since leaving that path out could hand the root to the rest. Because the root comes from the checkpoint, a session whose exported checkpoint changes is re-indexed even if its transcript did not. The root and the refs read the same FileChange tool calls (an assistant line's `tool_use` or `tool` block, the name in any case or JSON spelling), and the root is inferred from exactly the paths the refs are made from: a `move_path` counts only on an `update`.
 - `meta_hits` deterministic way-of-working classifier (review_request, validation_loop, handoff_resume, read_only_diagnosis, correction_followup, user_preference, no_egress_constraint).
 - `episode_facts` branch-scoped durable-fact links (text + locus overlap), graceful when no facts exist; facts never leak across branches.
 - Tool OUTPUT is never parsed as a command; everything is redacted at rest.
diff --git a/internal/cli/pattern_corpus_codex_items_test.go b/internal/cli/pattern_corpus_codex_items_test.go
index 6a4dfd5aa..2fef109fc 100644
--- a/internal/cli/pattern_corpus_codex_items_test.go
+++ b/internal/cli/pattern_corpus_codex_items_test.go
@@ -179,6 +179,57 @@ func TestCodexSessionRoot(t *testing.T) {
 	}
 }

+// The root and the stored refs come from the same FileChange calls: a block
+// the episode ops read as an edit votes for the root, and one they don't read
+// doesn't, so a session's edits are made relative exactly when the root
+// they'd vote for is found.
+func TestCodexFileChangeRootAndRefsAgree(t *testing.T) {
+	lines := func(records ...string) string { return strings.Join(records, "\n") + "\n" }
+	edit := codexFileChange(t, codexChange{Path: "/w/r/main.go", Kind: "update"})
+	cases := []struct {
+		name, transcript string
+		wantRoot         string
+		wantFiles        string
+	}{
+		{"a lowercase tool name is an edit and votes",
+			`{"v":1,"agent":"codex","type":"assistant","ts":"t","id":"f1","content":[{"id":"f1","input":{"changes":[{"path":"/w/r/main.go","kind":"update"}]},"name":"filechange","type":"tool_use"}]}` + "\n",
+			"/w/r", `["edit main.go"]`},
+		{"a FileChange that isn't a tool call doesn't vote", lines(edit,
+			`{"v":1,"agent":"codex","type":"assistant","ts":"t","id":"x1","content":[{"type":"text","text":"","name":"FileChange","input":{"changes":[{"path":"/tmp/x/main.go","kind":"update"}]}}]}`),
+			"/w/r", `["edit main.go"]`},
+		{"a FileChange on a user line doesn't vote", lines(edit,
+			`{"v":1,"agent":"codex","type":"user","ts":"t","id":"u1","content":[{"id":"f2","input":{"changes":[{"path":"/tmp/x/main.go","kind":"update"}]},"name":"FileChange","type":"tool_use"}]}`),
+			"/w/r", `["edit main.go"]`},
+		{"a move path on an add is not a ref and doesn't vote",
+			lines(codexFileChange(t, codexChange{Path: "/w/r/main.go", Kind: "add", MovePath: "/tmp/x/main.go"})),
+			"/w/r", `["add main.go"]`},
+		{"a .. move path on an add doesn't block the root",
+			lines(codexFileChange(t, codexChange{Path: "/w/r/main.go", Kind: "add", MovePath: "/w/r/x/../y.go"})),
+			"/w/r", `["add main.go"]`},
+		{"a native assistant message's FileChange is an edit and votes",
+			`{"type":"assistant","message":{"role":"assistant","content":[{"type":"tool_use","id":"f1","name":"FileChange","input":{"changes":[{"path":"/w/r/main.go","kind":"update"}]}}]}}` + "\n",
+			"/w/r", `["edit main.go"]`},
+		{"a tool name with a JSON escape is an edit and votes",
+			`{"v":1,"agent":"codex","type":"assistant","ts":"t","id":"f1","content":[{"id":"f1","input":{"changes":[{"path":"/w/r/main.go","kind":"update"}]},"name":"File\u0043hange","type":"tool_use"}]}` + "\n",
+			"/w/r", `["edit main.go"]`},
+		{"a tool name that only lowercases to filechange is an edit and votes",
+			`{"v":1,"agent":"codex","type":"assistant","ts":"t","id":"f1","content":[{"id":"f1","input":{"changes":[{"path":"/w/r/main.go","kind":"update"}]},"name":"F\u0130leChange","type":"tool_use"}]}` + "\n",
+			"/w/r", `["edit main.go"]`},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			root := codexSessionRoot(c.transcript, []string{"main.go"})
+			if root != c.wantRoot {
+				t.Errorf("root = %q, want %q", root, c.wantRoot)
+			}
+			_, _, files := corpusEpisodeOps(c.transcript, root)
+			if got := describeFileRefs(files); got != c.wantFiles {
+				t.Errorf("files = %s, want %s", got, c.wantFiles)
+			}
+		})
+	}
+}
+
 // codexItemPathCorpus is a brain with codex item-path sessions and a live
 // graph context whose semantic index has main.go's 2 symbols.
 type codexItemPathCorpus struct {
