86	func corpusEpisodeOps(workText, repoRoot string) (tools []corpusToolOp, commands []corpusCommand, files []corpusFileRef) {
87		exitByCall := map[string]int{}
88		failedByCall := map[string]bool{}
89		for i, line := range strings.Split(workText, "\n") {
90			line = strings.TrimSpace(line)
91			if !strings.HasPrefix(line, "{") {
92				continue
93			}
94			record, ok := decodeTranscriptRecord(line)
95			if !ok {
96				continue
97			}
98			ln := i + 1
99			uses := recordToolUses(record)
100			if record.etf != nil && strings.EqualFold(record.etf.Agent, "codex") {
101				compactCodexResults(uses, exitByCall, failedByCall)
102			}
103			obj := record.obj // nil for a format line, which matches no case below
104			switch jsonString(obj["type"]) {
105			case "response_item":
106				p := jsonMap(obj["payload"])
107				switch jsonString(p["type"]) {
108				case "function_call":
109					name := normalizeToolName(jsonString(p["name"]))
110					tools = append(tools, corpusToolOp{name: name, line: ln})
111					if cmd := shellCommandFromInput(name, p["arguments"]); cmd != "" {
112						if h := normalizeCommand(cmd); h != "" {
113							commands = append(commands, corpusCommand{head: h, raw: cmd, line: ln, callID: jsonString(p["call_id"])})
114						}
115					}
116				case "custom_tool_call":
117					name := normalizeToolName(jsonString(p["name"]))
118					tools = append(tools, corpusToolOp{name: name, line: ln})
119					files = append(files, patchFiles(jsonString(p["input"]), ln)...)
120				case "function_call_output", "custom_tool_call_output":
121					if id := jsonString(p["call_id"]); id != "" {
122						if code, ok := parseExitCode(jsonString(p["output"])); ok {
123							exitByCall[id] = code
124						}
125					}
126				case "patch_apply_end":
127					if id := jsonString(p["call_id"]); id != "" {
128						if code, ok := parseExitCode(jsonString(p["stdout"])); ok {
129							exitByCall[id] = code
130						}
131					}
132				}
133			}
134			t, c, f := toolUseOps(uses, repoRoot, ln)
135			tools = append(tools, t...)
136			commands = append(commands, c...)
137			files = append(files, f...)
138		}
139		// Correlate exit codes, and failures that carry none, to their commands.
140		for i := range commands {
141			if commands[i].callID == "" {
142				continue
